/* Search pill + overlay */
.search-pill {
  position: fixed;
  top: 16px;
  right: 16px;
  z-index: 50;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  padding: 0 12px 0 10px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(18, 18, 26, 0.85);
  backdrop-filter: blur(10px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
  color: #9898a8;
  font: 500 12px/1 "IBM Plex Sans", "Segoe UI", system-ui, sans-serif;
  cursor: pointer;
  transition: border-color 0.2s ease, color 0.2s ease;
}

.search-pill:hover {
  border-color: rgba(255, 255, 255, 0.18);
  color: #e8e8ec;
}

.search-pill-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #8ab4ff;
  box-shadow: 0 0 8px rgba(138, 180, 255, 0.7);
  flex-shrink: 0;
}

.search-kbd {
  font-family: "IBM Plex Mono", ui-monospace, monospace;
  font-size: 10px;
  font-weight: 500;
  color: #7a7a8c;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 5px;
  padding: 2px 6px;
  background: rgba(255, 255, 255, 0.03);
}

body.search-open .search-pill,
body.embed-active .search-pill {
  opacity: 0;
  pointer-events: none;
}

.search-overlay {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: grid;
  place-items: center;
  padding: 24px;
  pointer-events: none;
}

.search-overlay[hidden] {
  display: none;
}

body.search-mode-a .search-overlay {
  background: rgba(8, 8, 12, 0.42);
  backdrop-filter: blur(4px);
  pointer-events: auto;
}

body.search-mode-b .search-overlay {
  background: transparent;
  backdrop-filter: none;
  pointer-events: none;
}

.search-palette {
  width: min(460px, 100%);
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: linear-gradient(145deg, #1c1c26 0%, #12121a 100%);
  box-shadow:
    0 28px 60px rgba(0, 0, 0, 0.55),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  overflow: hidden;
  opacity: 0;
  transform: scale(0.96) translateY(8px);
  transition:
    opacity 0.22s ease,
    transform 0.28s cubic-bezier(0.34, 1.2, 0.64, 1);
  pointer-events: auto;
}

body.search-mode-a.search-open .search-palette {
  opacity: 1;
  transform: scale(1) translateY(0);
}

body.search-mode-b .search-palette {
  opacity: 0;
  transform: scale(0.96) translateY(8px);
  pointer-events: none;
  visibility: hidden;
}

.search-input-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.search-input-icon {
  color: #8ab4ff;
  font-size: 15px;
  line-height: 1;
}

.search-input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: none;
  background: transparent;
  color: #f4f4f8;
  font: 500 15px/1.2 "IBM Plex Sans", "Segoe UI", system-ui, sans-serif;
}

.search-input::placeholder {
  color: #7a7a8c;
  font-weight: 400;
}

.search-results {
  list-style: none;
  max-height: min(320px, 50vh);
  overflow-y: auto;
  padding: 6px 0;
}

.search-result {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  width: 100%;
  padding: 10px 14px;
  border: 0;
  border-left: 2px solid transparent;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.search-result:hover {
  background: rgba(255, 255, 255, 0.03);
}

.search-result.is-active {
  background: rgba(138, 180, 255, 0.14);
  border-left-color: #8ab4ff;
}

.search-result-tag {
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #7a7a8c;
  margin-bottom: 2px;
}

.search-result-title {
  font-size: 13px;
  font-weight: 600;
  color: #f4f4f8;
}

.search-result-title mark {
  background: transparent;
  color: #8ab4ff;
  font-weight: 700;
}

.search-result-hint {
  font-size: 11px;
  color: #9898a8;
  margin-top: 2px;
}

.search-result-hint mark {
  background: transparent;
  color: #8ab4ff;
}

.search-result-score {
  margin-left: auto;
  font-family: "IBM Plex Mono", ui-monospace, monospace;
  font-size: 10px;
  color: #7a7a8c;
  padding-top: 2px;
  flex-shrink: 0;
}

.search-empty {
  padding: 20px 16px;
  font-size: 13px;
  color: #9898a8;
  text-align: center;
}

.search-footer {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 10px 14px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  font-size: 11px;
  color: #7a7a8c;
}

.search-spotlight-hud {
  position: absolute;
  top: 16px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px;
