import * as THREE from "three";
import { CSS3DRenderer, CSS3DObject } from "three/addons/renderers/CSS3DRenderer.js";
import Fuse from "fuse.js";

const PROJECT_MANIFESTS = ["./projects/sots.json", "./projects/paper2qb.json"];

let runtimeEmbeds = {};

async function loadRuntimeEmbeds() {
  try {
    const response = await fetch("./dev-config.json", { cache: "no-store" });
    if (!response.ok) return {};
    return await response.json();
  } catch {
    return {};
  }
}

const STATIC_PROJECTS = [
  {
    tag: "Systems",
    title: "Dotfiles",
    description:
      "Shell, editor, and tooling configuration tuned for daily development on macOS.",
    url: "https://github.com/yeungsinchun/dotfiles",
  },
  {
    tag: "Coursework",
    title: "Final Year Project",
    description:
      "Capstone research and implementation work from undergraduate studies.",
    url: "https://github.com/yeungsinchun/FYP",
  },
];

async function loadProjects() {
  const manifests = await Promise.all(
    PROJECT_MANIFESTS.map(async (path) => {
      const response = await fetch(path);
      if (!response.ok) {
        throw new Error(`Failed to load project manifest: ${path}`);
      }
      return response.json();
    })
  );
  return [...manifests, ...STATIC_PROJECTS];
}

function assetUrl(path) {
  return new URL(path, document.baseURI).href;
}

function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function highlightIndices(text, indices) {
  if (!indices?.length) return escapeHtml(text);

  const merged = [];
  for (const [start, end] of indices) {
    const last = merged[merged.length - 1];
    if (last && start <= last[1] + 1) {
      last[1] = Math.max(last[1], end);
    } else {
      merged.push([start, end]);
    }
  }

  let html = "";
  let cursor = 0;
  for (const [start, end] of merged) {
    html += escapeHtml(text.slice(cursor, start));
    html += `<mark>${escapeHtml(text.slice(start, end + 1))}</mark>`;
    cursor = end + 1;
  }
  html += escapeHtml(text.slice(cursor));
  return html;
}

function indicesForKey(matches, key) {
  const entry = matches?.find((item) => item.key === key);
  return entry?.indices ?? null;
}

async function setModalScreenshot(container, path, alt) {
  const url = assetUrl(path);
  container.setAttribute("aria-label", alt);
  container.replaceChildren();

  if (path.endsWith(".svg")) {
    try {
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }
      const markup = await response.text();
      container.insertAdjacentHTML("beforeend", markup);
      const svg = container.querySelector("svg");
      if (svg) {
        svg.setAttribute("width", "100%");
        svg.setAttribute("height", "100%");
        svg.setAttribute("preserveAspectRatio", "xMidYMid meet");
      }
      return;
    } catch (error) {
      console.warn("Failed to inline SVG preview, falling back to image tag:", error);
    }
  }

  const image = document.createElement("img");
  image.src = url;
  image.alt = alt;
  container.appendChild(image);
}

function resolveEmbedUrl(project) {
  const runtimeUrl = project.id ? runtimeEmbeds[project.id]?.embedUrl : null;
  if (runtimeUrl) return runtimeUrl;

  const embed = project.detail?.embedUrl;
  if (!embed) return null;

  const isLocal =
    location.hostname === "localhost" || location.hostname === "127.0.0.1";

  if (isLocal && embed.development) {
    return embed.development;
  }
  if (embed.production) {
    return embed.production;
  }
  return embed.development || null;
}

function initEmbed(onClose) {
  const embedView = document.getElementById("embed-view");
  const embedFrame = document.getElementById("embed-frame");
  const embedTitle = document.getElementById("embed-title");
  const embedBack = document.getElementById("embed-back");

  let loadedUrl = "";

  function openEmbed(project, url) {
    embedTitle.textContent = project.title;
    if (loadedUrl !== url) {
      embedFrame.src = url;
      loadedUrl = url;
    }
    embedView.hidden = false;
    document.body.classList.add("embed-active");
    embedBack.focus();
  }

  function closeEmbed() {
    embedView.hidden = true;
    document.body.classList.remove("embed-active");
    onClose();
  }

  function isOpen() {
    return !embedView.hidden;
  }

  embedBack.addEventListener("click", closeEmbed);

  window.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && isOpen()) {
      closeEmbed();
    }
  });

  return { openEmbed, isOpen };
}

function initModal({ openEmbed }) {
  const modal = document.getElementById("project-modal");
  const screenshot = document.getElementById("modal-screenshot");
  const tag = document.getElementById("modal-tag");
  const title = document.getElementById("modal-title");
  const summary = document.getElementById("modal-summary");
  const github = document.getElementById("modal-github");
  const paper = document.getElementById("modal-paper");
  const glimpseButton = document.getElementById("modal-glimpse");

  let activeProject = null;
  let closeTimer = null;

  function isOpen() {
    return !modal.hidden;
  }

  function closeModal() {
    if (modal.hidden) return;
    modal.classList.remove("is-open");
    clearTimeout(closeTimer);
    closeTimer = setTimeout(() => {
      modal.hidden = true;
      modal.setAttribute("aria-hidden", "true");
      activeProject = null;
    }, 340);
  }

  async function openModal(project) {
    if (!project.detail) {
      if (project.url) {
        window.open(project.url, "_blank", "noopener,noreferrer");
      }
      return;
    }

    activeProject = project;
    const detail = project.detail;

    tag.textContent = project.tag;
    title.textContent = project.title;
    summary.textContent = detail.summary;
    if (project.url) {
      github.href = project.url;
      github.hidden = false;
    } else {
      github.hidden = true;
    }
    await setModalScreenshot(
      screenshot,
      detail.screenshot,
      `${project.title} preview`
    );

    if (detail.paperUrl) {
      paper.href = detail.paperUrl;
      paper.hidden = false;
    } else {
      paper.hidden = true;
    }

    const embedUrl = resolveEmbedUrl(project);
    glimpseButton.hidden = !embedUrl;

    clearTimeout(closeTimer);
    modal.hidden = false;
    modal.setAttribute("aria-hidden", "false");
    modal.classList.remove("is-open");
    requestAnimationFrame(() => {
      requestAnimationFrame(() => modal.classList.add("is-open"));
    });
    glimpseButton.focus();
  }

  function closeModalImmediate() {
    clearTimeout(closeTimer);
    modal.classList.remove("is-open");
    modal.hidden = true;
    modal.setAttribute("aria-hidden", "true");
    activeProject = null;
  }

  modal.querySelectorAll("[data-modal-close]").forEach((element) => {
    element.addEventListener("click", closeModal);
  });

  window.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && isOpen() && !document.body.classList.contains("search-open")) {
      closeModal();
    }
  });

  glimpseButton.addEventListener("click", () => {
    if (!activeProject) return;
    const embedUrl = resolveEmbedUrl(activeProject);
    if (!embedUrl) return;
    const project = activeProject;
    closeModalImmediate();
    openEmbed(project, embedUrl);
  });

  return { openModal, closeModal, isOpen };
}

function initCards(projects, { openModal }) {
  const container = document.getElementById("canvas-container");
  const scene = new THREE.Scene();

  const camera = new THREE.PerspectiveCamera(
    45,
    window.innerWidth / window.innerHeight,
    1,
    5000
  );
  camera.position.z = 1200;

  const renderer = new CSS3DRenderer();
  renderer.setSize(window.innerWidth, window.innerHeight);
  container.appendChild(renderer.domElement);

  const cards = [];
  const cardSpacing = 320;
  const startX = -((projects.length - 1) * cardSpacing) / 2;
  let animationRunning = true;
  let searchMode = null;
  let searchActiveId = null;
  let searchMatchIds = new Set();

  const focusTilts = [
    { x: -0.22, y: 0.35 },
    { x: 0.18, y: -0.28 },
    { x: -0.14, y: -0.4 },
    { x: 0.26, y: 0.22 },
  ];

  projects.forEach((project, index) => {
    const hasDetail = Boolean(project.detail);
    const projectKey = project.id || `static-${index}`;
    const element = document.createElement("div");
    element.className = "card";
    element.dataset.projectKey = projectKey;
    element.innerHTML = `
      <span class="card-tag">${escapeHtml(project.tag)}</span>
      <h2 class="card-title">${escapeHtml(project.title)}</h2>
      <p class="card-desc">${escapeHtml(project.description)}</p>
      ${
        hasDetail
          ? `<span class="card-link">Learn more</span>`
          : `<a class="card-link" href="${escapeHtml(project.url)}" target="_blank" rel="noopener noreferrer">View project</a>`
      }
    `;

    const object = new CSS3DObject(element);
    object.position.x = startX + index * cardSpacing;
    object.position.y = 0;
    scene.add(object);

    const state = {
      project,
      projectKey,
      element,
      object,
      homeX: object.position.x,
      homeY: 0,
      focusTilt: focusTilts[index % focusTilts.length],
      angularVelocity: new THREE.Vector2(0, 0),
      pointer: { x: 0, y: 0, time: 0 },
    };
    cards.push(state);

    element.addEventListener("pointermove", (event) => {
      if (searchMode) return;

      const now = performance.now();
      const dt = now - state.pointer.time;

      if (dt > 0 && state.pointer.time > 0) {
        const dx = event.clientX - state.pointer.x;
        const dy = event.clientY - state.pointer.y;
        const speedX = dx / dt;
        const speedY = dy / dt;

        const spinScale = 0.035;
        state.angularVelocity.x = -speedY * spinScale;
        state.angularVelocity.y = speedX * spinScale;
      }

      state.pointer.x = event.clientX;
      state.pointer.y = event.clientY;
      state.pointer.time = now;
    });

    element.addEventListener("click", (event) => {
      if (event.target.closest("a")) return;
      if (searchMode === "b" && !searchMatchIds.has(projectKey)) return;

      if (hasDetail) {
        openModal(project);
        return;
      }

      window.open(project.url, "_blank", "noopener,noreferrer");
    });
  });

  function applySearchClasses() {
    for (const card of cards) {
      const { element, projectKey } = card;
      element.classList.remove("search-dimmed", "search-match", "search-lit");

      if (!searchMode) continue;

      const isMatch = searchMatchIds.has(projectKey);
      const isLit = projectKey === searchActiveId;

      if (searchMode === "b") {
        if (isLit) {
          element.classList.add("search-lit", "search-match");
        } else if (isMatch) {
          element.classList.add("search-match");
        } else {
          element.classList.add("search-dimmed");
        }
      }
    }
  }

  function setSearchState({ mode = null, matchKeys = [], activeKey = null } = {}) {
    searchMode = mode;
    searchMatchIds = new Set(matchKeys);
    searchActiveId = activeKey;
    applySearchClasses();
  }

  function animate() {
    requestAnimationFrame(animate);

    if (!animationRunning) return;

    for (const card of cards) {
      const { object, angularVelocity, homeX, homeY, focusTilt, projectKey } = card;
      const isLit = searchMode === "b" && projectKey === searchActiveId;
      const isDimmed = searchMode === "b" && !searchMatchIds.has(projectKey);

      if (searchMode === "b") {
        const targetX = isLit ? focusTilt.x : isDimmed ? 0 : focusTilt.x * 0.35;
        const targetY = isLit ? focusTilt.y : isDimmed ? 0 : focusTilt.y * 0.35;
        const targetPosY = isLit ? 36 : isDimmed ? -12 : 8;
        const targetScale = isLit ? 1.08 : isDimmed ? 0.92 : 0.98;

        object.rotation.x += (targetX - object.rotation.x) * 0.12;
        object.rotation.y += (targetY - object.rotation.y) * 0.12;
        object.position.y += (homeY + targetPosY - object.position.y) * 0.12;
        object.position.x += (homeX - object.position.x) * 0.08;
        object.scale.setScalar(
          object.scale.x + (targetScale - object.scale.x) * 0.12
        );
        angularVelocity.set(0, 0);
      } else if (searchMode === "a") {
        object.rotation.x *= 0.9;
        object.rotation.y *= 0.9;
        object.position.y += (homeY - object.position.y) * 0.1;
        object.position.x += (homeX - object.position.x) * 0.1;
        object.scale.setScalar(object.scale.x + (1 - object.scale.x) * 0.1);
        angularVelocity.set(0, 0);
      } else {
        object.rotation.x += angularVelocity.x;
        object.rotation.y += angularVelocity.y;
        angularVelocity.multiplyScalar(0.88);
        object.rotation.x *= 0.96;
        object.rotation.y *= 0.96;
        object.position.y += (homeY - object.position.y) * 0.08;
        object.position.x += (homeX - object.position.x) * 0.08;
        object.scale.setScalar(object.scale.x + (1 - object.scale.x) * 0.1);
      }
    }

    renderer.render(scene, camera);
  }

  function onResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  }

  window.addEventListener("resize", onResize);
  animate();

  return {
    resume() {
      animationRunning = true;
    },
    setSearchState,
  };
}

function initSearch(projects, { openModal, isEmbedOpen, cardScene }) {
  const overlay = document.getElementById("search-overlay");
  const palette = document.getElementById("search-palette");
  const input = document.getElementById("search-input");
  const resultsEl = document.getElementById("search-results");
  const pill = document.getElementById("search-pill");
  const spotlightHud = document.getElementById("search-spotlight-hud");
  const hudQuery = document.getElementById("search-hud-query");
  const hudCount = document.getElementById("search-hud-count");

  const indexed = projects.map((project, index) => ({
    ...project,
    projectKey: project.id || `static-${index}`,
    searchText: [
      project.title,
      project.tag,
      project.description,
      project.detail?.summary,
      project.id,
    ]
      .filter(Boolean)
      .join(" "),
  }));

  const fuse = new Fuse(indexed, {
    keys: [
      { name: "title", weight: 0.45 },
      { name: "tag", weight: 0.2 },
      { name: "description", weight: 0.2 },
      { name: "detail.summary", weight: 0.1 },
      { name: "id", weight: 0.05 },
    ],
    threshold: 0.42,
    ignoreLocation: true,
    includeMatches: true,
    includeScore: true,
    minMatchCharLength: 1,
  });

  let open = false;
  let mode = "a";
  let query = "";
  let hits = [];
  let activeIndex = 0;

  function isOpen() {
    return open;
  }

  function syncBodyClasses() {
    document.body.classList.toggle("search-open", open);
    document.body.classList.toggle("search-mode-a", open && mode === "a");
    document.body.classList.toggle("search-mode-b", open && mode === "b");
  }

  function runQuery(nextQuery) {
    query = nextQuery;
    if (!query.trim()) {
      hits = indexed.map((project) => ({
        item: project,
        score: 1,
        matches: [],
      }));
    } else {
      hits = fuse.search(query);
    }
    if (activeIndex >= hits.length) activeIndex = Math.max(0, hits.length - 1);
    render();
  }

  function renderResults() {
    resultsEl.replaceChildren();

    if (!hits.length) {
      const empty = document.createElement("li");
      empty.className = "search-empty";
      empty.textContent = query.trim()
        ? "No projects match that query."
        : "Start typing to filter projects.";
      resultsEl.appendChild(empty);
      return;
    }

    hits.forEach((hit, index) => {
      const project = hit.item;
      const li = document.createElement("li");
      li.setAttribute("role", "presentation");

      const button = document.createElement("button");
      button.type = "button";
      button.className = `search-result${index === activeIndex ? " is-active" : ""}`;
      button.setAttribute("role", "option");
      button.setAttribute("aria-selected", index === activeIndex ? "true" : "false");
      button.id = `search-option-${index}`;

      const titleHtml = highlightIndices(
        project.title,
        indicesForKey(hit.matches, "title")
      );
      const hintSource = project.description || project.detail?.summary || "";
      const hintHtml = highlightIndices(
        hintSource,
        indicesForKey(hit.matches, "description") ||
          indicesForKey(hit.matches, "detail.summary")
      );
      const score =
        typeof hit.score === "number" ? (1 - hit.score).toFixed(2) : "—";

      button.innerHTML = `
        <div>
          <div class="search-result-tag">${escapeHtml(project.tag)}</div>
          <div class="search-result-title">${titleHtml}</div>
          <div class="search-result-hint">${hintHtml}</div>
        </div>
        <span class="search-result-score">${score}</span>
      `;

      button.addEventListener("click", () => {
        activeIndex = index;
        selectActive();
      });
      button.addEventListener("mousemove", () => {
        if (activeIndex !== index) {
          activeIndex = index;
          render();
        }
      });

      li.appendChild(button);
      resultsEl.appendChild(li);
    });

    input.setAttribute(
      "aria-activedescendant",
      hits.length ? `search-option-${activeIndex}` : ""
    );
  }

  function renderHud() {
    const showHud = open && mode === "b";
    spotlightHud.hidden = !showHud;
    hudQuery.textContent = query.trim() || "all";
    hudCount.textContent = hits.length
      ? `${activeIndex + 1} / ${hits.length}`
      : "0";
  }

  function syncCards() {
    const matchKeys = hits.map((hit) => hit.item.projectKey);
    const activeKey = hits[activeIndex]?.item.projectKey ?? null;
    cardScene.setSearchState({
      mode: open ? mode : null,
      matchKeys: open ? matchKeys : [],
      activeKey: open ? activeKey : null,
    });
  }

  function render() {
    renderResults();
    renderHud();
    syncCards();
    syncBodyClasses();
  }

  function openSearch() {
    if (open || isEmbedOpen()) return;
    open = true;
    mode = "a";
    overlay.hidden = false;
    overlay.setAttribute("aria-hidden", "false");
    runQuery(input.value);
    syncBodyClasses();
    requestAnimationFrame(() => input.focus());
  }

  function closeSearch() {
    if (!open) return;
    open = false;
    mode = "a";
    overlay.hidden = true;
    overlay.setAttribute("aria-hidden", "true");
    spotlightHud.hidden = true;
    cardScene.setSearchState({ mode: null, matchKeys: [], activeKey: null });
    syncBodyClasses();
    input.blur();
  }

  function setMode(nextMode) {
    if (!open || mode === nextMode) return;
    mode = nextMode;
    render();
    if (mode === "a") {
      requestAnimationFrame(() => input.focus());
    } else {
      input.blur();
    }
  }

  function moveActive(delta) {
    if (!hits.length) return;
    activeIndex = (activeIndex + delta + hits.length) % hits.length;
    render();
    const activeButton = resultsEl.querySelector(".search-result.is-active");
    activeButton?.scrollIntoView({ block: "nearest" });
  }

  function selectActive() {
    const hit = hits[activeIndex];
    if (!hit) return;
    const project = hit.item;
    closeSearch();
    openModal(project);
  }

  pill.addEventListener("click", openSearch);

  input.addEventListener("input", () => {
    activeIndex = 0;
    runQuery(input.value);
  });

  palette.addEventListener("mousedown", (event) => {
    if (event.target === input) return;
    // Keep focus behavior predictable when clicking results
  });

  window.addEventListener("keydown", (event) => {
    if (isEmbedOpen()) return;

    const metaK =
      (event.key === "k" || event.key === "K") && (event.metaKey || event.ctrlKey);

    if (metaK) {
      event.preventDefault();
      if (open) {
        closeSearch();
      } else {
        openSearch();
      }
      return;
    }

    if (!open) return;

    if (event.key === "Escape") {
      event.preventDefault();
      closeSearch();
      return;
    }

    if (event.key === "Tab") {
      event.preventDefault();
      setMode(mode === "a" ? "b" : "a");
      return;
    }

    if (event.key === "ArrowDown" || (event.key === "j" && mode === "b")) {
      event.preventDefault();
      moveActive(1);
      return;
    }

    if (event.key === "ArrowUp" || (event.key === "k" && mode === "b")) {
      event.preventDefault();
      moveActive(-1);
      return;
    }

    if (event.key === "Enter") {
      event.preventDefault();
      selectActive();
      return;
    }

    // In spotlight mode, typing returns to palette and updates the query
    if (
      mode === "b" &&
      event.key.length === 1 &&
      !event.metaKey &&
      !event.ctrlKey &&
      !event.altKey
    ) {
      setMode("a");
      requestAnimationFrame(() => {
        input.focus();
      });
    }
  });

  return { openSearch, closeSearch, isOpen };
}

async function main() {
  const [projects, embeds] = await Promise.all([
    loadProjects(),
    loadRuntimeEmbeds(),
  ]);
  runtimeEmbeds = embeds;

  const cardScene = {
    resume() {},
    setSearchState() {},
  };
  const { openEmbed, isOpen: isEmbedOpen } = initEmbed(() => cardScene.resume());
  const { openModal } = initModal({ openEmbed });

  Object.assign(cardScene, initCards(projects, { openModal }));
  initSearch(projects, { openModal, isEmbedOpen, cardScene });
}

main().catch((error) => {
  console.error(error);
});

