import { marked } from "https://cdn.jsdelivr.net/npm/marked@15.0.7/lib/marked.esm.js";

const DEFAULT_POST = "streaming-delta-notes";

function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function parseFrontmatter(source) {
  const match = source.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/);
  if (!match) {
    return { meta: {}, body: source };
  }

  const meta = {};
  for (const line of match[1].split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const idx = trimmed.indexOf(":");
    if (idx === -1) continue;
    const key = trimmed.slice(0, idx).trim();
    let value = trimmed.slice(idx + 1).trim();
    if (value.startsWith("#")) value = "";
    const commentIdx = value.indexOf(" #");
    if (commentIdx !== -1) value = value.slice(0, commentIdx).trim();
    meta[key] = value;
  }

  return { meta, body: match[2].trim() };
}

function formatDate(value) {
  if (!value) return "";
  const date = new Date(`${value}T00:00:00`);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleDateString("en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
}

function postSlugFromLocation() {
  const params = new URLSearchParams(location.search);
  const fromQuery = params.get("p") || params.get("id");
  if (fromQuery) return fromQuery.replace(/\.md$/i, "");

  const hash = location.hash.replace(/^#/, "").trim();
  if (hash) return hash.replace(/\.md$/i, "");

  return DEFAULT_POST;
}

function renderMeta(meta) {
  const parts = [];
  const date = formatDate(meta.date);
  if (date) parts.push(`<span>${escapeHtml(date)}</span>`);
  if (meta.minutes) parts.push(`<span>${escapeHtml(meta.minutes)} min</span>`);
  if (meta.project) {
    parts.push(
      `<a href="../?project=${encodeURIComponent(meta.project)}">${escapeHtml(meta.project)}</a>`
    );
  }
  return parts.join('<span aria-hidden="true"> · </span>');
}

async function loadPost(slug) {
  const response = await fetch(`../posts/${encodeURIComponent(slug)}.md`, {
    cache: "no-store",
  });
  if (!response.ok) {
    throw new Error(`Post not found: ${slug}`);
  }
  return response.text();
}

async function main() {
  const status = document.getElementById("writing-status");
  const article = document.getElementById("writing-article");
  const titleEl = document.getElementById("writing-title");
  const tagEl = document.getElementById("writing-tag");
  const metaEl = document.getElementById("writing-meta");
  const bodyEl = document.getElementById("writing-body");
  const barTitle = document.getElementById("writing-bar-title");

  const slug = postSlugFromLocation();

  try {
    const source = await loadPost(slug);
    const { meta, body } = parseFrontmatter(source);

    if (meta.draft === "true") {
      throw new Error("This post is marked draft and is not published.");
    }

    const title = meta.title || slug;
    document.title = title;
    barTitle.textContent = title;
    titleEl.textContent = title;
    tagEl.textContent = meta.tag || "Notes";
    metaEl.innerHTML = renderMeta(meta);
    bodyEl.innerHTML = marked.parse(body);

    status.hidden = true;
    article.hidden = false;
  } catch (error) {
    console.error(error);
    status.hidden = false;
    status.className = "writing-error";
    status.textContent = error.message || "Failed to load post.";
    article.hidden = true;
    barTitle.textContent = "Writing";
  }
}

main();

