const PROJECT_MANIFESTS = ["./projects/sots.json", "./projects/paper2qb.json"];
const POSTS_MANIFEST = "./posts/manifest.json";

let runtimeEmbeds = {};

async function loadRuntimeEmbeds() {
  try {
    const response = await fetch("./dev-config.json", { cache: "no-store" });
    if (!response.ok) return {};
    return await response.json();
  } catch {
    return {};
  }
}

const STATIC_PROJECTS = [
  {
    tag: "Systems",
    title: "Dotfiles",
    description:
      "Shell, editor, and tooling configuration tuned for daily development on macOS.",
    url: "https://github.com/yeungsinchun/dotfiles",
  },
  {
    tag: "Coursework",
    title: "Final Year Project",
    description:
      "Capstone research and implementation work from undergraduate studies.",
    url: "https://github.com/yeungsinchun/FYP",
  },
];

async function loadProjects() {
  const manifests = await Promise.all(
    PROJECT_MANIFESTS.map(async (path) => {
      const response = await fetch(path);
      if (!response.ok) {
        throw new Error(`Failed to load project manifest: ${path}`);
      }
      return response.json();
    })
  );
  return manifests.map((project) => ({ ...project, kind: "project" })).concat(
    STATIC_PROJECTS.map((project, index) => ({
      ...project,
      kind: "project",
      id: project.id || `static-${index}`,
    }))
  );
}

async function loadPosts() {
  try {
    const response = await fetch(POSTS_MANIFEST, { cache: "no-store" });
    if (!response.ok) return [];
    const entries = await response.json();
    return entries.map((post) => ({
      kind: "post",
      id: post.id,
      tag: post.tag || "Notes",
      title: post.title,
      description: post.summary || "",
      summary: post.summary || "",
      minutes: post.minutes,
      date: post.date,
      project: post.project,
      writingUrl: `./writing/?p=${encodeURIComponent(post.id)}`,
    }));
  } catch (error) {
    console.warn("Failed to load posts manifest:", error);
    return [];
  }
}

function openItem(item, { openModal }) {
  if (item.kind === "post") {
    window.location.href = item.writingUrl;
    return;
  }
  openModal(item);
}

