function initCards(items, { openModal }) {
  const container = document.getElementById("canvas-container");
  const scene = new THREE.Scene();

  const camera = new THREE.PerspectiveCamera(
    45,
    window.innerWidth / window.innerHeight,
    1,
    5000
  );
  camera.position.z = 1400;

  const renderer = new CSS3DRenderer();
  renderer.setSize(window.innerWidth, window.innerHeight);
  container.appendChild(renderer.domElement);

  const cards = [];
  const cardSpacing = 320;
  let animationRunning = true;
  let searchMode = null;
  let searchActiveId = null;
  let searchMatchIds = new Set();

  const focusTilts = [
    { x: -0.22, y: 0.35 },
    { x: 0.18, y: -0.28 },
    { x: -0.14, y: -0.4 },
    { x: 0.26, y: 0.22 },
  ];

  const projects = items.filter((item) => item.kind === "project");
  const posts = items.filter((item) => item.kind === "post");

  const SECTION_GAP = 520;
  const PROJECTS_Y = posts.length ? SECTION_GAP / 2 : 0;
  const WRITING_Y = posts.length ? -SECTION_GAP / 2 : 0;

  function addSectionLabel(text, y, className = "") {
    const element = document.createElement("div");
    element.className = `section-label${className ? ` ${className}` : ""}`;
    element.textContent = text;
    const object = new CSS3DObject(element);
    object.position.set(0, y + 260, 0);
    scene.add(object);
    return object;
  }

  function addCard(item, indexInRow, rowCount, homeY, tiltIndex) {
    const isPost = item.kind === "post";
    const hasDetail = Boolean(item.detail);
    const itemKey = item.id || `${item.kind}-${tiltIndex}`;
    const element = document.createElement("div");
    element.className = isPost ? "card card-writing" : "card";
    element.dataset.projectKey = itemKey;
    element.dataset.kind = item.kind;

    const linkLabel = isPost
      ? "Read note"
      : hasDetail
        ? "Learn more"
        : null;

    element.innerHTML = `
      <span class="card-tag">${escapeHtml(item.tag)}</span>
      <h2 class="card-title">${escapeHtml(item.title)}</h2>
      <p class="card-desc">${escapeHtml(item.description)}</p>
      ${
        linkLabel
          ? `<span class="card-link">${linkLabel}</span>`
          : `<a class="card-link" href="${escapeHtml(item.url)}" target="_blank" rel="noopener noreferrer">View project</a>`
      }
    `;

    const startX = -((rowCount - 1) * cardSpacing) / 2;
    const object = new CSS3DObject(element);
    object.position.x = startX + indexInRow * cardSpacing;
    object.position.y = homeY;
    scene.add(object);

    const state = {
      item,
      projectKey: itemKey,
      kind: item.kind,
      element,
      object,
      homeX: object.position.x,
      homeY,
      focusTilt: focusTilts[tiltIndex % focusTilts.length],
      angularVelocity: new THREE.Vector2(0, 0),
      pointer: { x: 0, y: 0, time: 0 },
    };
    cards.push(state);

    element.addEventListener("pointermove", (event) => {
      if (searchMode) return;

      const now = performance.now();
      const dt = now - state.pointer.time;

      if (dt > 0 && state.pointer.time > 0) {
        const dx = event.clientX - state.pointer.x;
        const dy = event.clientY - state.pointer.y;
        const speedX = dx / dt;
        const speedY = dy / dt;

        const spinScale = 0.035;
        state.angularVelocity.x = -speedY * spinScale;
        state.angularVelocity.y = speedX * spinScale;
      }

      state.pointer.x = event.clientX;
      state.pointer.y = event.clientY;
      state.pointer.time = now;
    });

    element.addEventListener("click", (event) => {
      if (event.target.closest("a")) return;
      if (searchMode === "b" && !searchMatchIds.has(itemKey)) return;
      openItem(item, { openModal });
    });
  }

  if (projects.length) {
    addSectionLabel("Projects", PROJECTS_Y);
    projects.forEach((item, index) => {
      addCard(item, index, projects.length, PROJECTS_Y, index);
    });
  }

  if (posts.length) {
    addSectionLabel("Writing", WRITING_Y, "section-label-writing");
    posts.forEach((item, index) => {
      addCard(item, index, posts.length, WRITING_Y, projects.length + index);
    });
  }

  function applySearchClasses() {
    for (const card of cards) {
      const { element, projectKey } = card;
      element.classList.remove("search-dimmed", "search-match", "search-lit");

      if (!searchMode) continue;

      const isMatch = searchMatchIds.has(projectKey);
      const isLit = projectKey === searchActiveId;

      if (searchMode === "b") {
        if (isLit) {
          element.classList.add("search-lit", "search-match");
        } else if (isMatch) {
          element.classList.add("search-match");
        } else {
          element.classList.add("search-dimmed");
        }
      }
    }
  }

  function setSearchState({ mode = null, matchKeys = [], activeKey = null } = {}) {
    searchMode = mode;
    searchMatchIds = new Set(matchKeys);
    searchActiveId = activeKey;
    applySearchClasses();
  }

  function animate() {
    requestAnimationFrame(animate);

    if (!animationRunning) return;

    for (const card of cards) {
      const { object, angularVelocity, homeX, homeY, focusTilt, projectKey } = card;
      const isLit = searchMode === "b" && projectKey === searchActiveId;
      const isDimmed = searchMode === "b" && !searchMatchIds.has(projectKey);

      if (searchMode === "b") {
        const targetX = isLit ? focusTilt.x : isDimmed ? 0 : focusTilt.x * 0.35;
        const targetY = isLit ? focusTilt.y : isDimmed ? 0 : focusTilt.y * 0.35;
        const targetPosY = isLit ? homeY + 36 : isDimmed ? homeY - 12 : homeY + 8;
        const targetScale = isLit ? 1.08 : isDimmed ? 0.92 : 0.98;

        object.rotation.x += (targetX - object.rotation.x) * 0.12;
        object.rotation.y += (targetY - object.rotation.y) * 0.12;
        object.position.y += (targetPosY - object.position.y) * 0.12;
        object.position.x += (homeX - object.position.x) * 0.08;
        object.scale.setScalar(
          object.scale.x + (targetScale - object.scale.x) * 0.12
        );
        angularVelocity.set(0, 0);
      } else if (searchMode === "a") {
        object.rotation.x *= 0.9;
        object.rotation.y *= 0.9;
        object.position.y += (homeY - object.position.y) * 0.1;
        object.position.x += (homeX - object.position.x) * 0.1;
        object.scale.setScalar(object.scale.x + (1 - object.scale.x) * 0.1);
        angularVelocity.set(0, 0);
      } else {
        object.rotation.x += angularVelocity.x;
        object.rotation.y += angularVelocity.y;
        angularVelocity.multiplyScalar(0.88);
        object.rotation.x *= 0.96;
        object.rotation.y *= 0.96;
        object.position.y += (homeY - object.position.y) * 0.08;
        object.position.x += (homeX - object.position.x) * 0.08;
        object.scale.setScalar(object.scale.x + (1 - object.scale.x) * 0.1);
      }
    }

    renderer.render(scene, camera);
  }

  function onResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  }

  window.addEventListener("resize", onResize);
  animate();

  return {
    resume() {
      animationRunning = true;
    },
    setSearchState,
  };
}

